1	import { io, Socket } from 'socket.io-client';
2	import { MatchData, ChatMessage } from '../types';
3	
4	const SERVER_URL = import.meta.env.VITE_SERVER_URL || 'http://localhost:3001';
5	
6	class SocketService {
7	  private socket: Socket | null = null;
8	  private listeners: Map<string, Set<Function>> = new Map();
9	
10	  connect(): Promise<void> {
11	    return new Promise((resolve, reject) => {
12	      this.socket = io(SERVER_URL, {
13	        transports: ['websocket', 'polling'],
14	        reconnection: true,
15	        reconnectionAttempts: 5,
16	        reconnectionDelay: 1000,
17	      });
18	
19	      this.socket.on('connect', () => {
20	        console.log('Connected to server:', this.socket?.id);
21	        resolve();
22	      });
23	
24	      this.socket.on('connect_error', (error) => {
25	        console.error('Connection error:', error);
26	        reject(error);
27	      });
28	
29	      this.socket.on('disconnect', (reason) => {
30	        console.log('Disconnected from server:', reason);
31	      });
32	
33	      // Set up event listeners
34	      this.setupEventListeners();
35	    });
36	  }
37	
38	  private setupEventListeners() {
39	    if (!this.socket) return;
40	
41	    const events = [
42	      'queueJoined',
43	      'queueLeft',
44	      'matchFound',
45	      'gameStart',
46	      'opponentMove',
47	      'gameOver',
48	      'error',
49	      'chatMessage',
50	      'webrtc-offer',
51	      'webrtc-answer',
52	      'webrtc-ice-candidate',
53	    ];
54	
55	    events.forEach((event) => {
56	      this.socket!.on(event, (data) => {
57	        this.emit(event, data);
58	      });
59	    });
60	  }
61	
62	  private emit(event: string, data: any) {
63	    const listeners = this.listeners.get(event) || new Set();
64	    listeners.forEach((listener) => listener(data));
65	  }
66	
67	  on(event: string, callback: Function): () => void {
68	    if (!this.listeners.has(event)) {
69	      this.listeners.set(event, new Set());
70	    }
71	    this.listeners.get(event)!.add(callback);
72	
73	    // Return unsubscribe function
74	    return () => {
75	      this.listeners.get(event)?.delete(callback);
76	    };
77	  }
78	
79	  joinQueue() {
80	    this.socket?.emit('joinQueue');
81	  }
82	
83	  leaveQueue() {
84	    this.socket?.emit('leaveQueue');
85	  }
86	
87	  makeMove(gameId: string, move: string, fen: string) {
88	    this.socket?.emit('makeMove', { gameId, move, fen });
89	  }
90	
91	  resign(gameId: string) {
92	    this.socket?.emit('resign', { gameId });
93	  }
94	
95	  sendChatMessage(gameId: string, message: string) {
96	    this.socket?.emit('chatMessage', { gameId, message });
97	  }
98	
99	  // WebRTC signaling
100	  sendWebRTCOffer(gameId: string, offer: RTCSessionDescriptionInit, from: string) {
101	    this.socket?.emit('webrtc-offer', { gameId, offer, from });
102	  }
103	
104	  sendWebRTCAnswer(gameId: string, answer: RTCSessionDescriptionInit, from: string) {
105	    this.socket?.emit('webrtc-answer', { gameId, answer, from });
106	  }
107	
108	  sendWebRTCIceCandidate(gameId: string, candidate: RTCIceCandidateInit, from: string) {
109	    this.socket?.emit('webrtc-ice-candidate', { gameId, candidate, from });
110	  }
111	
112	  disconnect() {
113	    this.socket?.disconnect();
114	    this.socket = null;
115	    this.listeners.clear();
116	  }
117	
118	  getId(): string | undefined {
119	    return this.socket?.id;
120	  }
121	
122	  isConnected(): boolean {
123	    return this.socket?.connected || false;
124	  }
125	}
126	
127	export const socketService = new SocketService();

