2	import { Chessboard } from 'react-chessboard';
3	import { Chess, Move as ChessMove } from 'chess.js';
4	import { useGame } from '../context/GameContext';
5	
6	export function ChessBoardPanel() {
7	  const { gameState, chess, makeMove } = useGame();
8	
9	  function onDrop(sourceSquare: string, targetSquare: string, piece: string): boolean {
10	    if (!gameState.isPlaying || !gameState.isMyTurn || gameState.gameOver) {
11	      return false;
12	    }
13	
14	    try {
15	      const move: ChessMove = {
16	        from: sourceSquare,
17	        to: targetSquare,
18	        promotion: 'q', // Always promote to queen for simplicity
19	      };
20	
21	      // Check if the move is valid
22	      const tempChess = new Chess(chess.fen());
23	      const result = tempChess.move(move);
24	      
25	      if (result) {
26	        makeMove(move);
27	        return true;
28	      }
29	      return false;
30	    } catch (error) {
31	      return false;
32	    }
33	  }
34	
35	  const getBoardOrientation = () => {
36	    return gameState.playerColor === 'black' ? 'black' : 'white';
37	  };
38	
39	  const getStatusMessage = () => {
40	    if (gameState.gameOver) {
41	      if (gameState.winner) {
42	        if (gameState.winner === gameState.playerColor) {
43	          return '🎉 You won!';
44	        } else {
45	          return '😔 You lost';
46	        }
47	      } else {
48	        return '🤝 Draw';
49	      }
50	    }
51	
52	    if (!gameState.isPlaying) {
53	      if (gameState.isMatched) {
54	        return 'Waiting for game to start...';
55	      }
56	      return '';
57	    }
58	
59	    if (gameState.isMyTurn) {
60	      return 'Your turn';
61	    } else {
62	      return "Opponent's turn";
63	    }
64	  };
65	
66	  const customPieces = () => {
67	    const pieces: { [piece: string]: React.FC<{ squareWidth: number }> } = {};
68	    return pieces;
69	  };
70	
71	  return (
72	    <div className="chess-panel">
73	      <div className="game-status">
74	        <div className="status-text">{getStatusMessage()}</div>
75	        {gameState.isPlaying && !gameState.gameOver && (
76	          <div className="turn-indicator">
77	            {gameState.isMyTurn ? (
78	              <span className="my-turn">⏱️ Your turn</span>
79	            ) : (
80	              <span className="opponent-turn">⏳ Waiting...</span>
81	            )}
82	          </div>
83	        )}
84	      </div>
85	
86	      <div className="chessboard-container">
87	        {gameState.isPlaying ? (
88	          <Chessboard
89	            id="ChessBoard"
90	            position={gameState.fen}
91	            onPieceDrop={onDrop}
92	            boardOrientation={getBoardOrientation()}
93	            animationDuration={300}
94	            customDarkSquareStyle={{ backgroundColor: '#779556' }}
95	            customLightSquareStyle={{ backgroundColor: '#ebecd0' }}
96	            arePiecesDraggable={gameState.isMyTurn && !gameState.gameOver}
97	            customBoardStyle={{
98	              borderRadius: '4px',
99	              boxShadow: '0 2px 10px rgba(0, 0, 0, 0.3)',
100	            }}
101	          />
