109	              </svg>
110	            </div>
111	            <p>
112	              {gameState.isMatched 
113	                ? 'Waiting for game to start...' 
114	                : 'Join the queue to find a match'}
115	            </p>
116	          </div>
117	        )}
118	      </div>
119	
120	      {gameState.isPlaying && (
121	        <div className="game-info">
122	          <div className="player-info">
123	            <span className="player-color">
124	              {gameState.playerColor === 'white' ? '⚪ White' : '⚫ Black'}
125	            </span>
126	            <span className="player-you">(You)</span>
127	          </div>
128	          <div className="vs">VS</div>
129	          <div className="player-info">
130	            <span className="player-color">
131	              {gameState.playerColor === 'white' ? '⚫ Black' : '⚪ White'}
132	            </span>
133	            <span className="player-opponent">(Opponent)</span>
134	          </div>
135	        </div>
