// Test Harness for Chess Roulette App
// Provides direct access to app state for fast verification (~5ms calls)
// Only active in development mode

declare global {
  interface Window {
    __TEST_API__?: {
      _meta: {
        name: string;
        framework: string;
        stateLib: string;
        createdBy: string;
      };
      actions: Record<string, (...args: any[]) => any>;
      queries: Record<string, (...args: any[]) => any>;
    };
  }
}

// This file will be imported in the App entry point
// It exposes semantic actions and queries for testing the chess-roulette app

if (typeof window !== 'undefined' && import.meta.env.DEV) {
  window.__TEST_API__ = {
    _meta: {
      name: 'Chess Roulette',
      framework: 'react',
      stateLib: 'context',
      createdBy: 'fabric-agent',
    },
    actions: {
      // Placeholder actions - actual implementation requires context access
      connect: async () => {
        console.log('Connect action called');
      },

      disconnect: async () => {
        console.log('Disconnect action called');
      },

      joinQueue: () => {
        console.log('Join queue action called');
      },

      leaveQueue: () => {
        console.log('Leave queue action called');
      },

      makeMove: (from: string, to: string) => {
        console.log(`Make move: ${from} to ${to}`);
      },

      resign: (gameId: string) => {
        console.log(`Resign game: ${gameId}`);
      },

      sendChatMessage: (gameId: string, message: string) => {
        console.log(`Send chat: ${message}`);
      },

      toggleVideo: (enabled: boolean) => {
        console.log(`Toggle video: ${enabled}`);
      },

      toggleAudio: (enabled: boolean) => {
        console.log(`Toggle audio: ${enabled}`);
      },

      switchCamera: async () => {
        console.log('Switch camera');
      },

      // DOM actions (using page API when available)
      clickElement: async (selector: string) => {
        if ((window as any).page) {
          await (window as any).page.click(selector);
        }
      },

      fillInput: async (selector: string, value: string) => {
        if ((window as any).page) {
          await (window as any).page.fill(selector, value);
        }
      },
    },
    queries: {
      // Connection state
      isConnected: () => false,
      getSocketId: () => null,

      // Game state queries (would need access to context)
      getGameState: () => null,
      isQueued: () => false,
      isMatched: () => false,
      isPlaying: () => false,
      getFEN: () => 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
      isMyTurn: () => true,
      getGameStatus: () => 'waiting',

      // DOM queries
      getBoardOrientation: () => 'white',
      getTurnIndicator: () => null,
      getStatusMessage: () => null,
      getChatMessages: () => [],
      getVideoStatus: (isLocal: boolean) => false,

      // Chess board queries
      getBoardPosition: () => {
        try {
          const { Chess } = require('chess.js');
          const chess = new Chess();
          return chess.fen();
        } catch {
          return 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';
        }
      },

      isValidMove: (from: string, to: string) => {
        try {
          const { Chess } = require('chess.js');
          const chess = new Chess();
          const move = chess.move({ from, to, promotion: 'q' });
          return !!move;
        } catch {
          return false;
        }
      },

      getLegalMoves: (square: string) => {
        try {
          const { Chess } = require('chess.js');
          const chess = new Chess();
          const moves = chess.moves({ square, verbose: true });
          return moves.map((m: any) => m.to);
        } catch {
          return [];
        }
      },

      isCheckmate: () => false,
      isDraw: () => false,
      isStalemate: () => false,
    },
  };
}

